<?php declare(strict_types=1); namespace Core\Http; use Core\Exceptions\Handler; use Core\Foundation\Application; use Throwable; class Kernel { public function __construct( private readonly Application $app, private readonly Router $router, ) { } public function handle(Request $request): Response { $this->app->instance(Request::class, $request); try { return $this->router->dispatch($request); } catch (Throwable $e) { return Handler::render($e, $request); } } public function terminate(): void { } } 